const delay = (ms, value) =>
  new Promise((resolve) => {
    setTimeout(() => {
      console.log("done " + value);
      resolve(value);
    }, ms);
  });

Promise.all([delay(40, "north"), Promise.reject(new Error("road closed")), delay(10, "south")])
  .then((routes) => console.log(routes.join(",")))
  .catch((error) => console.log("caught " + error.message));
